-- Catalog imported from Amazon Brazil deals by the local n8n workflow (specs/product.md)

-- nanoid-style id (21 URL-safe chars) generated by the database. The import
-- upserts on asin without sending id, so an existing product keeps its id
-- (feedback references it) and its first_seen_at.
create function public.products_nanoid()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  alphabet constant text :=
    '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_-';
  -- two random v4 uuids; bytes 6 and 8 of each carry fixed version bits, so skip them
  bytes bytea := uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid());
  result text := '';
  i int := 0;
begin
  while char_length(result) < 21 loop
    if i % 16 not in (6, 8) then
      result := result || substr(alphabet, (get_byte(bytes, i) & 63) + 1, 1);
    end if;
    i := i + 1;
  end loop;
  return result;
end;
$$;

create table public.products (
  id text primary key default public.products_nanoid(),
  asin text not null unique,                    -- Amazon id; the import upserts on it
  title text not null check (char_length(title) between 1 and 500),
  url text not null,                            -- canonical https://www.amazon.com.br/dp/<ASIN>
  image_url text not null,                      -- m.media-amazon.com only
  price_cents integer not null check (price_cents >= 0),
  list_price_cents integer check (list_price_cents >= 0),
  discount_percent smallint check (discount_percent between 0 and 100),
  currency text not null default 'BRL' check (currency = 'BRL'),
  rating numeric(2, 1) check (rating between 0 and 5),
  review_count integer check (review_count >= 0),
  category_slug text not null,
  category_name text not null,
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  search tsvector generated always as (to_tsvector('portuguese', title)) stored
);

-- Full-text search over titles (searchProducts)
create index products_search_idx on public.products using gin (search);

-- Category lists, newest first (listProducts with a category)
create index products_category_seen_idx
  on public.products (category_slug, last_seen_at desc);

-- "Biggest discounts" and "Top rated" lists
create index products_discount_idx
  on public.products (discount_percent desc nulls last);
create index products_rating_idx
  on public.products (rating desc nulls last, review_count desc nulls last);

-- Availability filter (seen in the last 3 days)
create index products_last_seen_idx on public.products (last_seen_at);

-- No policies: only the server (service role) can read or write products.
alter table public.products enable row level security;

-- Categories with available products and their counts (listCategories).
-- PostgREST has aggregates off by default, so the grouping lives here.
create function public.list_product_categories(since timestamptz)
returns table (slug text, name text, count bigint)
language sql
stable
set search_path = ''
as $$
  select category_slug, max(category_name), count(*)
  from public.products
  where last_seen_at > since
  group by category_slug
  order by count(*) desc, category_slug;
$$;

-- Only the server (service role) uses these functions.
revoke execute on function public.products_nanoid() from public, anon, authenticated;
revoke execute on function public.list_product_categories(timestamptz)
  from public, anon, authenticated;
